// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PredictTheBlockHashChallenge} from "../src/PredictTheBlockHashChallenge.sol";

contract InvMutTest is Test {
    PredictTheBlockHashChallenge c;
    function setUp() public { c = new PredictTheBlockHashChallenge{value: 1 ether}(); }

    function testFuzz_property(address actor, bytes32 hash, uint256 startBlock) public {
        vm.assume(actor != address(0));
        vm.assume(actor != address(c));
        startBlock = bound(startBlock, 1, type(uint64).max / 2);

        vm.roll(startBlock);
        vm.deal(actor, 1 ether);
        vm.prank(actor);
        c.lockInGuess{value: 1 ether}(hash);

        // One block later: in the reference contract the recorded target block is
        // startBlock + 1, which is still not in the past, so settle() must revert.
        vm.roll(startBlock + 1);
        vm.prank(actor);
        bool ok;
        try c.settle() { ok = true; } catch { ok = false; }
        assertTrue(!ok, "settle must revert before the target block has passed");
    }
}
